tool_use_result.originalFile:
import { getDb, DatabaseUnavailableError } from '../db';
import { createLogger } from '../_core/logger';

const logger = createLogger('database', { component: 'DeploymentPersistence' });
import { deploymentRecords, deploymentScans, monitorCycles, governanceDeploySnapshots } from '../../drizzle/schema';
import { desc, eq, sql } from 'drizzle-orm';
import type { MonitorCycleResult } from './autonomous-experiment-monitor';

export async function persistDeploymentRecord(record: {
  deploymentId: string;
  status: string;
  source: string;
  patchCount: number;
  filesAffected: string[];
  durationMs: number;
  error?: string;
  metadata?: Record<string, unknown>;
}): Promise<void> {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot persist deployment record');
    await db.insert(deploymentRecords).values({
      deploymentId: record.deploymentId,
      status: record.status,
      source: record.source,
      patchCount: record.patchCount,
      filesAffected: JSON.stringify(record.filesAffected),
      durationMs: record.durationMs,
      error: record.error || null,
      metadata: record.metadata ? JSON.stringify(record.metadata) : null,
      createdAt: Date.now(),
    });
  } catch (err) {
    logger.error({ err, operation: 'deploy', deploymentId: record.deploymentId }, 'Failed to persist deployment record');
  }
}

export async function getDeploymentRecords(limit = 50) {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot read deployment records');
    return await db.select().from(deploymentRecords).orderBy(desc(deploymentRecords.createdAt)).limit(limit);
  } catch { return []; }
}

export async function getDeploymentRecord(deploymentId: string) {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot read deployment record');
    const r = await db.select().from(deploymentRecords).where(eq(deploymentRecords.deploymentId, deploymentId)).limit(1);
    return r[0] || null;
  } catch { return null; }
}

export async function persistScanResult(scan: {
  scanId: string;
  deploymentId: string;
  overallScore: number;
  passed: boolean;
  checksRun: number;
  checksPassed: number;
  checksFailed: number;
  details?: Record<string, unknown>;
}): Promise<void> {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot persist scan result');
    await db.insert(deploymentScans).values({
      scanId: scan.scanId,
      deploymentId: scan.deploymentId,
      overallScore: scan.overallScore,
      passed: scan.passed ? 1 : 0,
      checksRun: scan.checksRun,
      checksPassed: scan.checksPassed,
      checksFailed: scan.checksFailed,
      details: scan.details ? JSON.stringify(scan.details) : null,
      createdAt: Date.now(),
    });
  } catch (err) {
    logger.error({ err, operation: 'scan', scanId: scan.scanId }, 'Failed to persist scan result');
  }
}

export async function getScanResults(limit = 50) {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot read scan results');
    return await db.select().from(deploymentScans).orderBy(desc(deploymentScans.createdAt)).limit(limit);
  } catch { return []; }
}

export async function getScansForDeployment(deploymentId: string) {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot read scans for deployment');
    return await db.select().from(deploymentScans).where(eq(deploymentScans.deploymentId, deploymentId));
  } catch { return []; }
}

export async function persistMonitorCycle(cycle: MonitorCycleResult): Promise<void> {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot persist monitor cycle');
    await db.insert(monitorCycles).values({
      cycleId: cycle.cycleId,
      startedAt: cycle.startedAt,
      completedAt: cycle.completedAt,
      experimentsChecked: cycle.experimentsChecked,
      promoted: JSON.stringify(cycle.promoted),
      rolledBack: JSON.stringify(cycle.rolledBack),
      ongoing: JSON.stringify(cycle.ongoing),
      errors: JSON.stringify(cycle.errors),
      createdAt: Date.now(),
    });
  } catch (err) {
    logger.error({ err, operation: 'monitor', cycleId: cycle.cycleId }, 'Failed to persist monitor cycle');
  }
}

export async function getMonitorCycles(limit = 50) {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot read monitor cycles');
    return await db.select().from(monitorCycles).orderBy(desc(monitorCycles.createdAt)).limit(limit);
  } catch { return []; }
}

export async function persistGovernanceSnapshot(snapshot: {
  deploymentId: string;
  phase: 'pre' | 'post';
  overallScore: number;
  coveragePercent: number;
  healthStatus: string;
  details?: Record<string, unknown>;
}): Promise<void> {
  try {
    const db = await getDb();
    if (!db) throw new DatabaseUnavailableError('Database unavailable: cannot persist governance snapshot');
    await db.insert(governanceDeploySnapshots).values({
      deploymentId: snapshot.deploymentId,
      phase: snapshot.phase,
      overallScore: snapshot.overallScore,
      coveragePercent: snapshot.coveragePercent,
      healthStatus: snapshot.healthStatus,
      details: snapshot.details ? JSON.stringify(snapshot.details) : null,
      createdAt: Date.now(),
    });
  } catch (err) {
    logger.error({ err, operation: 'governance', deploymentId: snapshot.deploymentId }, 'Failed to persist governance snapshot');
  }
}

export async function getGovernanceSnapshots(limit = 50) {
  try {
    const db = await getDb();
    return await db.select().from(governanceDeploySnapshots).orderBy(desc(governanceDeploySnapshots.createdAt)).limit(limit);
  } catch { return []; }
}

export async function getDeploymentStats() {
  try {
    const db = await getDb();
    const countQuery = sql<number>`COUNT(*)`;
    const [d, s, c, g] = await Promise.all([
      db.select({ count: countQuery }).from(deploymentRecords).then((r) => Number(r[0]?.count ?? 0)),
      db.select({ count: countQuery }).from(deploymentScans).then((r) => Number(r[0]?.count ?? 0)),
      db.select({ count: countQuery }).from(monitorCycles).then((r) => Number(r[0]?.count ?? 0)),
      db.select({ count: countQuery }).from(governanceDeploySnapshots).then((r) => Number(r[0]?.count ?? 0)),
    ]);
    return { totalDeployments: d, totalScans: s, totalMonitorCycles: c, totalGovernanceSnapshots: g };
  } catch {
    return { totalDeployments: 0, totalScans: 0, totalMonitorCycles: 0, totalGovernanceSnapshots: 0 };
  }
}

